def validate_splits(train_ids, validation_ids, test_ids):
    train=set(train_ids); validation=set(validation_ids); test=set(test_ids)
    if train & validation or train & test or validation & test:
        raise ValueError('dataset split leakage')
    manifest={'train':sorted(train),'validation':sorted(validation),'test':sorted(test)}
    return hashlib.sha256(json.dumps(manifest,sort_keys=True).encode()).hexdigest()

